-- Gexart CRM core schema.
-- Conventions:
--   * Primary keys are random UUID strings generated by the Worker.
--   * Timestamps are ISO-8601 UTC strings (e.g. 2026-10-29T08:15:00.000Z).
--   * Money is stored in minor units (paise/cents) as INTEGER next to an ISO currency code.
--   * Records that other records reference are archived (archived_at) rather than deleted.
--   * Allowed values for status/type columns mirror shared/enums.ts.

-- ───────────────────────── Users & sessions ─────────────────────────
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  name TEXT NOT NULL,
  role TEXT NOT NULL DEFAULT 'rep' CHECK (role IN ('admin','manager','rep')),
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  password_iterations INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata',
  last_login_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE sessions (
  id TEXT PRIMARY KEY,               -- SHA-256 of the cookie token; the raw token is never stored
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  ip TEXT,
  user_agent TEXT
);
CREATE INDEX idx_sessions_user ON sessions(user_id);

CREATE TABLE login_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  key TEXT NOT NULL,                 -- "email:<email>" or "ip:<ip>"
  created_at TEXT NOT NULL
);
CREATE INDEX idx_login_attempts_key ON login_attempts(key, created_at);

-- ───────────────────────── Catalogue & campaigns ─────────────────────────
CREATE TABLE products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  sku TEXT NOT NULL UNIQUE,
  category TEXT NOT NULL CHECK (category IN ('marketing','technology','other')),
  short_description TEXT,
  description TEXT,
  pricing_model TEXT NOT NULL DEFAULT 'custom' CHECK (pricing_model IN ('one_time','recurring','custom')),
  default_price_minor INTEGER,
  currency TEXT NOT NULL DEFAULT 'INR',
  billing_frequency TEXT CHECK (billing_frequency IN ('monthly','quarterly','yearly')),
  internal_cost_minor INTEGER,       -- admin/manager only; stripped from rep responses
  features TEXT,                     -- one deliverable per line
  target_industries TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  archived_at TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE campaigns (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  code TEXT NOT NULL UNIQUE,
  description TEXT,
  type TEXT NOT NULL CHECK (type IN ('outbound_email','prospecting','paid_ads','linkedin','referral','event','partnership','other')),
  objective TEXT,
  target_industry TEXT,
  target_geography TEXT,
  target_audience TEXT,
  owner_id TEXT REFERENCES users(id),
  start_date TEXT,
  end_date TEXT,
  budget_minor INTEGER,
  actual_spend_minor INTEGER,
  currency TEXT NOT NULL DEFAULT 'INR',
  target_leads INTEGER,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','planned','active','paused','completed','archived')),
  lead_source TEXT,
  notes TEXT,
  archived_at TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_campaigns_status ON campaigns(status);

CREATE TABLE campaign_products (
  campaign_id TEXT NOT NULL REFERENCES campaigns(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  created_at TEXT NOT NULL,
  PRIMARY KEY (campaign_id, product_id)
);

-- ───────────────────────── Accounts & contacts ─────────────────────────
CREATE TABLE accounts (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  name_normalized TEXT NOT NULL,
  legal_name TEXT,
  website TEXT,
  domain TEXT,                       -- normalized host of website, used for duplicate detection
  industry TEXT,
  company_size TEXT,
  business_type TEXT,
  country TEXT,
  state TEXT,
  city TEXT,
  address TEXT,
  postal_code TEXT,
  email TEXT,
  phone TEXT,
  linkedin_url TEXT,
  instagram_url TEXT,
  facebook_url TEXT,
  youtube_url TEXT,
  google_business_url TEXT,
  owner_id TEXT REFERENCES users(id),
  type TEXT NOT NULL DEFAULT 'prospect' CHECK (type IN ('prospect','customer','partner','former_customer','other')),
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','researching','contacted','engaged','qualified','active_customer','inactive','disqualified')),
  qualification TEXT CHECK (qualification IN ('high','medium','low','needs_research')),
  qualification_note TEXT,
  lead_source TEXT,
  source_campaign_id TEXT REFERENCES campaigns(id),
  source_prospect_id TEXT,
  notes TEXT,
  archived_at TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_accounts_owner ON accounts(owner_id);
CREATE INDEX idx_accounts_domain ON accounts(domain);
CREATE INDEX idx_accounts_name ON accounts(name_normalized);
CREATE INDEX idx_accounts_status ON accounts(status);

CREATE TABLE account_campaigns (
  account_id TEXT NOT NULL REFERENCES accounts(id),
  campaign_id TEXT NOT NULL REFERENCES campaigns(id),
  created_at TEXT NOT NULL,
  PRIMARY KEY (account_id, campaign_id)
);

CREATE TABLE account_products (
  account_id TEXT NOT NULL REFERENCES accounts(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  relationship TEXT NOT NULL CHECK (relationship IN ('pitched','proposed','sold')),
  created_at TEXT NOT NULL,
  PRIMARY KEY (account_id, product_id, relationship)
);

CREATE TABLE account_service_assessments (
  id TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES accounts(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  status TEXT NOT NULL CHECK (status IN ('not_assessed','needs_assessment','relevant','discussed','proposed','won','lost','not_applicable')),
  note TEXT,
  source TEXT NOT NULL DEFAULT 'user',  -- 'user' or 'audit:<run id>' when created from an audit finding
  updated_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE (account_id, product_id)
);

CREATE TABLE contacts (
  id TEXT PRIMARY KEY,
  account_id TEXT REFERENCES accounts(id),
  first_name TEXT NOT NULL,
  last_name TEXT,
  job_title TEXT,
  department TEXT,
  email TEXT,
  email_normalized TEXT,
  phone TEXT,
  phone_normalized TEXT,
  linkedin_url TEXT,
  owner_id TEXT REFERENCES users(id),
  decision_role TEXT CHECK (decision_role IN ('decision_maker','influencer','champion','user','gatekeeper','unknown')),
  preferred_channel TEXT CHECK (preferred_channel IN ('email','phone','linkedin','whatsapp','other')),
  status TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new','not_contacted','contacted','responded','engaged','qualified','unresponsive','do_not_contact')),
  last_contacted_at TEXT,
  next_follow_up_at TEXT,
  notes TEXT,
  source TEXT,
  source_prospect_id TEXT,
  archived_at TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_contacts_account ON contacts(account_id);
CREATE INDEX idx_contacts_owner ON contacts(owner_id);
CREATE INDEX idx_contacts_email ON contacts(email_normalized);
CREATE INDEX idx_contacts_phone ON contacts(phone_normalized);

-- ───────────────────────── Prospecting ─────────────────────────
CREATE TABLE prospects (
  id TEXT PRIMARY KEY,
  company_name TEXT NOT NULL,
  name_normalized TEXT NOT NULL,
  website TEXT,
  domain TEXT,
  industry TEXT,
  geography TEXT,
  company_size TEXT,
  contact_name TEXT,
  contact_title TEXT,
  email TEXT,
  phone TEXT,
  linkedin_url TEXT,
  discovery_source TEXT,
  campaign_id TEXT REFERENCES campaigns(id),
  service_fit TEXT,
  estimated_value_minor INTEGER,
  currency TEXT NOT NULL DEFAULT 'INR',
  status TEXT NOT NULL DEFAULT 'discovered' CHECK (status IN ('discovered','researching','to_qualify','qualified','converted','disqualified')),
  owner_id TEXT REFERENCES users(id),
  last_researched_at TEXT,
  research_notes TEXT,
  qualification_evidence TEXT,
  next_action TEXT,
  converted_account_id TEXT REFERENCES accounts(id),
  converted_contact_id TEXT REFERENCES contacts(id),
  converted_at TEXT,
  archived_at TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_prospects_status ON prospects(status);
CREATE INDEX idx_prospects_owner ON prospects(owner_id);
CREATE INDEX idx_prospects_domain ON prospects(domain);
CREATE INDEX idx_prospects_campaign ON prospects(campaign_id);

-- One row per conversion. The primary key makes a second conversion of the same
-- prospect fail, which rolls back the whole conversion batch.
CREATE TABLE prospect_conversions (
  prospect_id TEXT PRIMARY KEY REFERENCES prospects(id),
  account_id TEXT NOT NULL REFERENCES accounts(id),
  contact_id TEXT REFERENCES contacts(id),
  account_created INTEGER NOT NULL,
  campaign_id TEXT REFERENCES campaigns(id),
  converted_by TEXT REFERENCES users(id),
  converted_at TEXT NOT NULL
);

CREATE TABLE campaign_prospects (
  campaign_id TEXT NOT NULL REFERENCES campaigns(id),
  prospect_id TEXT NOT NULL REFERENCES prospects(id),
  created_at TEXT NOT NULL,
  PRIMARY KEY (campaign_id, prospect_id)
);

-- ───────────────────────── Pipeline ─────────────────────────
CREATE TABLE opportunities (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  account_id TEXT NOT NULL REFERENCES accounts(id),
  primary_contact_id TEXT REFERENCES contacts(id),
  campaign_id TEXT REFERENCES campaigns(id),
  owner_id TEXT REFERENCES users(id),
  amount_minor INTEGER NOT NULL DEFAULT 0,
  currency TEXT NOT NULL DEFAULT 'INR',
  expected_close_date TEXT,
  stage TEXT NOT NULL DEFAULT 'new' CHECK (stage IN ('new','discovery','qualified','meeting_scheduled','meeting_completed','proposal_prep','proposal_sent','negotiation','closed_won','closed_lost')),
  probability INTEGER NOT NULL DEFAULT 5 CHECK (probability BETWEEN 0 AND 100),
  next_action TEXT,
  competitors TEXT,
  proposal_url TEXT,
  win_loss_reason TEXT,
  notes TEXT,
  closed_at TEXT,
  archived_at TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_opps_account ON opportunities(account_id);
CREATE INDEX idx_opps_stage ON opportunities(stage);
CREATE INDEX idx_opps_owner ON opportunities(owner_id);

CREATE TABLE opportunity_products (
  id TEXT PRIMARY KEY,
  opportunity_id TEXT NOT NULL REFERENCES opportunities(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  quantity INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),
  unit_price_minor INTEGER NOT NULL DEFAULT 0,
  discount_pct REAL NOT NULL DEFAULT 0 CHECK (discount_pct BETWEEN 0 AND 100),
  currency TEXT NOT NULL DEFAULT 'INR',
  notes TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_opp_products_opp ON opportunity_products(opportunity_id);

-- ───────────────────────── Tasks & activities ─────────────────────────
CREATE TABLE tasks (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT,
  type TEXT NOT NULL DEFAULT 'general' CHECK (type IN ('follow_up_call','send_email','prepare_proposal','meeting','research','internal_review','general')),
  account_id TEXT REFERENCES accounts(id),
  contact_id TEXT REFERENCES contacts(id),
  prospect_id TEXT REFERENCES prospects(id),
  opportunity_id TEXT REFERENCES opportunities(id),
  due_at TEXT,
  priority TEXT NOT NULL DEFAULT 'medium' CHECK (priority IN ('low','medium','high','urgent')),
  owner_id TEXT REFERENCES users(id),
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','in_progress','completed','cancelled')),
  reminder_minutes INTEGER,
  completed_at TEXT,
  outcome TEXT,
  archived_at TEXT,
  created_by TEXT REFERENCES users(id),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_tasks_owner_status ON tasks(owner_id, status, due_at);
CREATE INDEX idx_tasks_account ON tasks(account_id);
CREATE INDEX idx_tasks_contact ON tasks(contact_id);
CREATE INDEX idx_tasks_prospect ON tasks(prospect_id);
CREATE INDEX idx_tasks_opp ON tasks(opportunity_id);

CREATE TABLE activities (
  id TEXT PRIMARY KEY,
  type TEXT NOT NULL CHECK (type IN ('note','call','email','meeting','linkedin','whatsapp','stage_change','status_change','conversion','audit','task_completed','system')),
  subject TEXT NOT NULL,
  body TEXT,
  account_id TEXT REFERENCES accounts(id),
  contact_id TEXT REFERENCES contacts(id),
  prospect_id TEXT REFERENCES prospects(id),
  opportunity_id TEXT REFERENCES opportunities(id),
  campaign_id TEXT REFERENCES campaigns(id),
  actor_id TEXT REFERENCES users(id),
  occurred_at TEXT NOT NULL,
  meta TEXT,                         -- JSON
  created_at TEXT NOT NULL
);
CREATE INDEX idx_activities_account ON activities(account_id, occurred_at);
CREATE INDEX idx_activities_contact ON activities(contact_id, occurred_at);
CREATE INDEX idx_activities_prospect ON activities(prospect_id, occurred_at);
CREATE INDEX idx_activities_opp ON activities(opportunity_id, occurred_at);
CREATE INDEX idx_activities_occurred ON activities(occurred_at);

-- ───────────────────────── Outreach (Phase 3 UI; schema ready now) ─────────────────────────
CREATE TABLE email_templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  category TEXT,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  intended_industry TEXT,
  product_id TEXT REFERENCES products(id),
  tone TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  owner_id TEXT REFERENCES users(id),
  archived_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE outreach_sequences (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  owner_id TEXT REFERENCES users(id),
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  archived_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE sequence_steps (
  id TEXT PRIMARY KEY,
  sequence_id TEXT NOT NULL REFERENCES outreach_sequences(id),
  position INTEGER NOT NULL,
  day_offset INTEGER NOT NULL,
  channel TEXT NOT NULL CHECK (channel IN ('manual_email','brevo','phone','linkedin','whatsapp','other')),
  template_id TEXT REFERENCES email_templates(id),
  task_type TEXT,
  note TEXT,
  UNIQUE (sequence_id, position)
);

CREATE TABLE outreach_messages (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  account_id TEXT REFERENCES accounts(id),
  contact_id TEXT REFERENCES contacts(id),
  prospect_id TEXT REFERENCES prospects(id),
  campaign_id TEXT REFERENCES campaigns(id),
  channel TEXT NOT NULL CHECK (channel IN ('manual_email','brevo','phone','linkedin','whatsapp','other')),
  template_id TEXT REFERENCES email_templates(id),
  subject TEXT,
  body TEXT,
  owner_id TEXT REFERENCES users(id),
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','ready_for_review','approved','sent','delivered','replied','bounced','failed','cancelled')),
  sent_via_integration INTEGER NOT NULL DEFAULT 0,  -- 1 only when an API confirmed the send
  planned_send_at TEXT,
  sent_at TEXT,
  replied_at TEXT,
  next_follow_up_at TEXT,
  outcome TEXT,
  provider_message_id TEXT UNIQUE,
  last_error TEXT,
  notes TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE INDEX idx_outreach_account ON outreach_messages(account_id);
CREATE INDEX idx_outreach_contact ON outreach_messages(contact_id);

CREATE TABLE webhook_events (
  provider TEXT NOT NULL,
  event_id TEXT NOT NULL,
  received_at TEXT NOT NULL,
  PRIMARY KEY (provider, event_id)    -- idempotency for duplicate webhook deliveries
);

-- ───────────────────────── Sales assets (Phase 4 UI; schema ready now) ─────────────────────────
CREATE TABLE sales_assets (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  type TEXT NOT NULL CHECK (type IN ('company_profile','brochure','proposal','case_study','presentation','pricing_sheet','contract','demo_link','audit_report','pitch_deck','template','other')),
  file_key TEXT,                     -- private R2 object key; served only through the authorized API
  file_name TEXT,
  mime_type TEXT,
  size_bytes INTEGER,
  external_url TEXT,
  intended_industry TEXT,
  version INTEGER NOT NULL DEFAULT 1,
  previous_version_id TEXT REFERENCES sales_assets(id),
  owner_id TEXT REFERENCES users(id),
  visibility TEXT NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal','confidential')),
  archived_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE asset_associations (
  asset_id TEXT NOT NULL REFERENCES sales_assets(id),
  entity_type TEXT NOT NULL CHECK (entity_type IN ('account','contact','campaign','opportunity','product','audit_run')),
  entity_id TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (asset_id, entity_type, entity_id)
);
CREATE INDEX idx_asset_assoc_entity ON asset_associations(entity_type, entity_id);

-- ───────────────────────── Platform ─────────────────────────
CREATE TABLE integrations (
  provider TEXT PRIMARY KEY,         -- 'manual_email', 'brevo', 'csv', ...
  enabled INTEGER NOT NULL DEFAULT 0,
  config TEXT,                       -- JSON, non-secret settings only; secrets live in Worker secrets
  last_success_at TEXT,
  last_error TEXT,
  last_error_at TEXT,
  updated_at TEXT NOT NULL
);

CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  type TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  entity_type TEXT,
  entity_id TEXT,
  read_at TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_notifications_user ON notifications(user_id, read_at);

CREATE TABLE audit_logs (
  id TEXT PRIMARY KEY,
  actor_id TEXT REFERENCES users(id),
  action TEXT NOT NULL,              -- create, update, archive, restore, convert, stage_change, login, ...
  entity_type TEXT NOT NULL,
  entity_id TEXT,
  summary TEXT,
  changes TEXT,                      -- JSON {field: [before, after]}
  ip TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_audit_logs_entity ON audit_logs(entity_type, entity_id, created_at);
CREATE INDEX idx_audit_logs_created ON audit_logs(created_at);
